import { generateObject } from 'ai';

/**
 * Temporary compatibility wrapper for the old `evaluate(...)` helper.
 *
 * Keep this module isolated from the harness-first API so legacy suites can be
 * removed cleanly in a later deletion pass.
 */

type LanguageModel = Parameters<typeof generateObject>[0]["model"];
/** Configures the default language model used by legacy `evaluate(...)`. */
declare function configure(opts: {
    model: LanguageModel;
}): void;
interface EvaluateOptions {
    task: () => Promise<string>;
    criteria: string;
    threshold?: number;
}
interface TestTaskContext {
    task: {
        meta: Record<string, any>;
    };
}
/** @internal Core evaluation logic, exported for testing. */
declare function _evaluate(ctx: TestTaskContext, opts: EvaluateOptions): Promise<void>;
/** Defines a legacy model-graded eval test. Prefer harness-backed suites. */
declare function evaluate(name: string, opts: EvaluateOptions & {
    timeout?: number;
}): void;

export { _evaluate, configure, evaluate };
